from decimal import Decimal

import pytest

from pricing.cart import LineItem
from pricing.bulk_discount import qualifies_for_bulk_discount, calculate_bulk_discount


class TestQualifiesForBulkDiscount:
    """Tests for the qualifies_for_bulk_discount function (Req 1.1, 1.2, 1.3)."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_10_qualifies(self) -> None:
        """WHEN a line item has a quantity of exactly 10 THEN it qualifies."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_qualifies(self) -> None:
        """WHEN a line item has a quantity greater than 10 THEN it qualifies."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=15)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify(self) -> None:
        """WHEN a line item has a quantity of 9 THEN it does not qualify."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_less_than_10_does_not_qualify(self) -> None:
        """WHEN a line item has a quantity less than 10 THEN it does not qualify."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=5)
        assert qualifies_for_bulk_discount(item) is False


class TestCalculateBulkDiscount:
    """Tests for the calculate_bulk_discount function (Req 1.1, 1.2, 1.3, 1.4)."""

    @pytest.mark.l4("C-8764baca", "C-1caf4da3")
    def test_discount_for_quantity_10(self) -> None:
        """WHEN quantity is 10 THEN 5% discount is applied with half-up rounding."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=10)
        # total = 100.00, 5% = 5.00
        assert calculate_bulk_discount(item) == Decimal("5.00")

    @pytest.mark.l4("C-e4015f6b", "C-1caf4da3")
    def test_discount_for_quantity_greater_than_10(self) -> None:
        """WHEN quantity > 10 THEN 5% discount is applied with half-up rounding."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=20)
        # total = 200.00, 5% = 10.00
        assert calculate_bulk_discount(item) == Decimal("10.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounding_half_up(self) -> None:
        """WHEN discount needs rounding THEN half-up rounding is used."""
        # Create a case where 5% results in a value requiring half-up rounding
        # total = 2.50, 5% = 0.125 -> should round to 0.13 with half-up
        item = LineItem(sku="SKU001", unit_price=Decimal("2.50"), quantity=10)
        assert calculate_bulk_discount(item) == Decimal("0.13")

    @pytest.mark.l4("C-4284227d")
    def test_no_discount_for_quantity_below_threshold(self) -> None:
        """WHEN quantity < 10 THEN no bulk discount is applied."""
        item = LineItem(sku="SKU001", unit_price=Decimal("10.00"), quantity=9)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-4284227d")
    def test_no_discount_for_quantity_1(self) -> None:
        """WHEN quantity is 1 THEN no bulk discount is applied."""
        item = LineItem(sku="SKU001", unit_price=Decimal("100.00"), quantity=1)
        assert calculate_bulk_discount(item) == Decimal("0.00")

